/*!
 * shellConnector.js - Shell Command Socket.IO Client Connector
 * Connects to shell-runner microservice via Socket.IO
 */

const debug = require('debug')('mutech:shell-connector');

class ShellConnector {
  constructor(io, db) {
    this.io = io;
    this.db = db;
    this.type = 'shell';

    // Connection state
    this.isRunnerConnected = false;
    this.runnerSocket = null;

    // Configuration
    this.requestTimeout = 10000; // 10 seconds

    this.setupShellNamespace();

    debug('Shell Connector initialized, waiting for runner connection');
  }

  setupShellNamespace() {
    // Setup namespace for shell-runner to connect to
    this.shellNamespace = this.io.of('/runner-shell');

    this.shellNamespace.on('connection', (socket) => {
      this.isRunnerConnected = true;
      this.runnerSocket = socket;
      debug('Shell runner connected: %s', socket.id);

      // Emit debug event
      this.emitDebugEvent('runner_connected', {
        runnerId: socket.id,
        timestamp: Date.now()
      });

      socket.on('disconnect', () => {
        this.isRunnerConnected = false;
        this.runnerSocket = null;
        debug('Shell runner disconnected: %s', socket.id);

        // Emit debug event
        this.emitDebugEvent('runner_disconnected', {
          runnerId: socket.id,
          timestamp: Date.now()
        });
      });
    });
  }

  async getState(unit) {
    const startTime = Date.now();

    try {
      debug('Getting state for unit: %s (%s)', unit.id, unit.args?.name || 'unnamed');

      // Check if runner is connected
      if (!this.isRunnerConnected || !this.runnerSocket) {
        const error = 'Shell runner not connected';
        debug('getState failed: %s', error);
        return {
          success: false,
          state: -1,
          error: error,
          unitType: this.type
        };
      }

      // Extract Status command from unit configuration
      const statusCommand = this.extractCommand(unit, 'Status');
      if (!statusCommand) {
        const error = 'No Status command found in unit configuration';
        debug('getState failed: %s', error);
        return {
          success: false,
          state: -1,
          error: error,
          unitType: this.type
        };
      }

      // Build structured request
      const request = {
        unitId: unit.id,
        operation: 'getState',
        command: statusCommand.cmd,
        onPattern: statusCommand.onMsg || '',
        offPattern: statusCommand.offMsg || '',
        timeout: this.getCommandTimeout(statusCommand)
      };

      // Send request with timeout
      const response = await this.sendRequestWithTimeout('executeCommand', request);

      if (response.success) {
        debug('getState success for unit: %s, state: %d', unit.id, response.state);

        return {
          success: true,
          state: response.state,
          unitType: this.type,
          output: response.output,
          duration: response.duration,
          timestamp: Date.now()
        };
      } else {
        debug('getState failed for unit: %s, error: %s', unit.id, response.error);
        return {
          success: false,
          state: -1,
          error: response.error,
          unitType: this.type
        };
      }

    } catch (error) {
      const duration = Date.now() - startTime;
      debug('getState exception for unit: %s, error: %s, duration: %dms', unit.id, error.message, duration);

      return {
        success: false,
        state: -1,
        error: error.message,
        unitType: this.type
      };
    }
  }

  async setState(unit, targetState) {
    const startTime = Date.now();

    try {
      const stateStr = targetState ? 'on' : 'off';
      debug('Setting state for unit: %s (%s) to %s', unit.id, unit.args?.name || 'unnamed', stateStr);

      // Check if runner is connected
      if (!this.isRunnerConnected || !this.runnerSocket) {
        const error = 'Shell runner not connected';
        debug('setState failed: %s', error);
        return {
          success: false,
          state: unit.state, // Keep current state
          error: error,
          unitType: this.type
        };
      }

      // Extract On/Off command from unit configuration
      const commandName = targetState ? 'On' : 'Off';
      const stateCommand = this.extractCommand(unit, commandName);
      if (!stateCommand) {
        const error = `No ${commandName} command found in unit configuration`;
        debug('setState failed: %s', error);
        return {
          success: false,
          state: unit.state, // Keep current state
          error: error,
          unitType: this.type
        };
      }

      // Build structured request
      const request = {
        unitId: unit.id,
        operation: 'setState',
        targetState: targetState ? 1 : 0,
        command: stateCommand.cmd,
        timeout: this.getCommandTimeout(stateCommand)
      };

      // Send request with timeout
      const response = await this.sendRequestWithTimeout('executeCommand', request);

      if (response.success) {
        const finalState = targetState ? 1 : 0;
        debug('setState success for unit: %s, state: %d, duration: %dms', unit.id, finalState, response.duration || 0);

        return {
          success: true,
          state: finalState,
          unitType: this.type,
          output: response.output,
          duration: response.duration,
          timestamp: Date.now()
        };
      } else {
        debug('setState failed for unit: %s, error: %s', unit.id, response.error);
        return {
          success: false,
          state: unit.state, // Keep current state on failure
          error: response.error,
          unitType: this.type
        };
      }

    } catch (error) {
      const duration = Date.now() - startTime;
      debug('setState exception for unit: %s, error: %s, duration: %dms', unit.id, error.message, duration);

      return {
        success: false,
        state: unit.state, // Keep current state on failure
        error: error.message,
        unitType: this.type
      };
    }
  }

  // Execute custom command by name (for non-automation units)
  async executeCommand(unit, commandName) {
    try {
      debug('Executing command "%s" for unit: %s (%s)', commandName, unit.id, unit.args?.name || 'unnamed');

      if (!this.isRunnerConnected || !this.runnerSocket) {
        return {
          success: false,
          error: 'Shell runner not connected'
        };
      }

      // Extract specific command from unit configuration
      const command = this.extractCommand(unit, commandName);
      if (!command) {
        return {
          success: false,
          error: `Command "${commandName}" not found in unit configuration`
        };
      }

      // Build structured request
      const request = {
        unitId: unit.id,
        operation: 'executeCommand',
        commandName: commandName,
        command: command.cmd,
        timeout: this.getCommandTimeout(command)
      };

      // Send request with timeout
      const response = await this.sendRequestWithTimeout('executeCommand', request);

      debug('executeCommand result for unit: %s, command: %s, success: %s', unit.id, commandName, response.success);

      return response;

    } catch (error) {
      debug('executeCommand exception for unit: %s, command: %s, error: %s', unit.id, commandName, error.message);
      return {
        success: false,
        error: error.message
      };
    }
  }

  // Extract command by name from unit.args.commands array
  extractCommand(unit, commandName) {
    if (!unit.args || !unit.args.commands || !Array.isArray(unit.args.commands)) {
      debug('Unit %s has no commands configuration', unit.id);
      return null;
    }

    const command = unit.args.commands.find(cmd => cmd.name === commandName);
    if (!command) {
      debug('Command "%s" not found in unit %s', commandName, unit.id);
      return null;
    }

    return command;
  }

  // Get timeout for command (from command config or default)
  getCommandTimeout(command) {
    // Check if command has specific timeout, otherwise use default
    if (command.timeout) {
      return parseInt(command.timeout);
    }
    return 5000; // 5 second default for shell commands
  }

  // Send request to runner with timeout
  sendRequestWithTimeout(event, data) {
    return new Promise((resolve, reject) => {
      if (!this.runnerSocket) {
        reject(new Error('Shell runner not connected'));
        return;
      }

      // Set timeout
      const timeoutId = setTimeout(() => {
        debug('Request timeout for event: %s, data: %o', event, data);
        this.emitDebugEvent('request_timeout', {
          event: event,
          data: data,
          timeout: this.requestTimeout,
          timestamp: Date.now()
        });
        reject(new Error(`Timeout waiting for Shell runner response (${this.requestTimeout}ms)`));
      }, this.requestTimeout);

      // Send request
      this.runnerSocket.emit(event, data, (response) => {
        clearTimeout(timeoutId);

        if (!response) {
          reject(new Error('No response from Shell runner'));
          return;
        }

        // Pass through response as-is
        resolve(response);
      });
    });
  }

  // Emit debug event to debug namespace
  emitDebugEvent(eventType, data) {
    try {
      this.io.of('/debug').emit('shellEvent', {
        type: eventType,
        data: data,
        timestamp: Date.now()
      });
    } catch (error) {
      // Don't let debug event emission fail the main operation
      debug('Error emitting debug event: %s', error.message);
    }
  }

  // Check if runner is connected
  isConnected() {
    return this.isRunnerConnected;
  }

  // Get connector information
  getConnectorInfo() {
    return {
      type: this.type,
      status: this.isRunnerConnected ? 'connected' : 'waiting',
      capabilities: ['getState', 'setState', 'executeCommand'],
      description: 'Shell Socket.IO connector - communicates with shell-runner microservice',
      runnerConnected: this.isRunnerConnected,
      requestTimeout: this.requestTimeout,
      method: 'socket.io-client',
      supportedOperations: {
        automation: ['getState', 'setState'], 
        manual: ['executeCommand']
      }
    };
  }

  // Disconnect (cleanup)
  disconnect() {
    debug('Shell Connector disconnecting');

    if (this.shellNamespace) {
      // Close namespace connections
      this.shellNamespace.disconnectSockets(true);
    }

    this.isRunnerConnected = false;
    this.runnerSocket = null;
  }
}

module.exports = ShellConnector;

