    35→
    36→    debug('Runner Coordinator initialized with runners: %o', Object.keys(this.connectors));
    37→    debug('Queue Manager and Timer Manager integrated and ready');
    38→  }
    39→
    40→  // Helper function for readable unit display
    41→  getUnitDisplayName(unit) {
    42→    const work = this.db.getWorkById(unit.parentId);
    43→    const exhibition = work ? this.db.getExhibits().find(e => e.id === work.parentId) : null;
    44→
    45→    const exhibitionName = exhibition?.name || 'Unknown Exhibition';
    46→    const workName = work?.name || 'Unknown Work';
    47→    const unitType = unit.unitType || 'unknown';
    48→    const host = unit.host && unit.host !== '#nohost' ? unit.host : 'nohost';
    49→
    50→    return `${exhibitionName} > ${workName} > ${unitType}@${host}`;
    51→  }
    52→
    53→  // Fast Path: Immediate execution (< 1s response requirement)
    54→  async executeImmediate(controlData, targetState) {
    55→    debug('🚀 IMMEDIATE execution (Fast Path): %s %s -> %s', controlData.type, controlData.id, targetState ? 'ON' : 'OFF');
    56→
    57→    try {
    58→      const units = this.getUnitsForControl(controlData);
    59→
    60→      if (units.length === 0) {
    61→        debug('No units found for immediate execution');
    62→        return { success: true, unitsProcessed: 0 };
    63→      }
    64→
    65→      debug('Fast Path processing %d units', units.length);
    66→
    67→      // Execute all units in parallel for maximum speed (bypasses queue entirely)
    68→      const promises = units.map(unit => this.executeUnitImmediate(unit, targetState));
    69→      const results = await Promise.all(promises);
    70→
    71→      // Update database states for successful operations
    72→      results.forEach(result => {
    73→        if (result.success && result.state !== undefined) {
    74→          this.updateUnitState(result.unit, result.state);
    75→        }
    76→      });
    77→
    78→      const successCount = results.filter(r => r.success).length;
    79→      debug('Fast Path completed: %d/%d units successful', successCount, units.length);
    80→
    81→      return {
    82→        success: true,
    83→        unitsProcessed: units.length,
    84→        successfulUnits: successCount,
    85→        results: results,
    86→        fastPath: true
    87→      };
    88→
    89→    } catch (error) {
    90→      debug('Error in immediate execution: %s', error.message);
    91→      throw error;
    92→    }
    93→  }
    94→
    95→  // Normal Path: Queued execution with rate limiting
    96→  async executeQueued(controlData, targetState) {
    97→    debug('📋 QUEUED execution (Normal Path): %s %s -> %s', controlData.type, controlData.id, targetState ? 'ON' : 'OFF');
    98→
    99→    try {
   100→      const units = this.getUnitsForControl(controlData);
   101→
   102→      if (units.length === 0) {
   103→        debug('No units found for queued execution');
   104→        return { success: true, unitsProcessed: 0 };
   105→      }
   106→
   107→      debug('Queuing %d units for rate-limited execution', units.length);
   108→
   109→      // Log which units are being queued (first few for brevity)
   110→      units.slice(0, 3).forEach(unit => {
   111→        debug('Queuing: %s', this.getUnitDisplayName(unit));
   112→      });
   113→      if (units.length > 3) {
   114→        debug('... and %d more units', units.length - 3);
   115→      }
   116→
   117→      // Create operations for all units
   118→      const operations = units.map(unit => ({
   119→        type: 'setState',
   120→        unit: unit,
   121→        targetState: targetState ? 1 : 0
   122→      }));
   123→
   124→      // Add to queue for rate-limited processing
   125→      const queueIds = this.queueManager.addBulkOperations(operations);
   126→
   127→      debug('Queued %d operations for rate-limited execution', operations.length);
   128→
   129→      return {
   130→        success: true,
   131→        unitsProcessed: units.length,
   132→        queueIds: queueIds,
   133→        fastPath: false,
   134→        message: `${units.length} operations queued for rate-limited execution`
   135→      };
   136→
   137→    } catch (error) {
   138→      debug('Error in queued execution: %s', error.message);
   139→      throw error;
   140→    }
   141→  }
   142→
   143→  // Execute single unit immediately (used by fast path and queue processor)
   144→  async executeUnitImmediate(unit, targetState) {
   145→    try {
   146→      const runner = this.getRunnerForUnit(unit);
   147→      if (!runner) {
   148→        debug('No runner found for unit type: %s', unit.unitType);
   149→        return {
   150→          success: false,
   151→          unit: unit.id,
   152→          error: 'No runner available',
   153→          unitType: unit.unitType
   154→        };
   155→      }
   156→
   157→      // Direct state change for maximum speed
   158→      const result = await runner.setState(unit, targetState);
