/*!
 * runnerCoordinator.js - Enhanced Coordinator with Queue and Timer Integration
 * Handles both queued (normal) and immediate (fast path) execution
 */

const debug = require('debug')('mutech:coordinator');

const ShellConnector = require('./shellConnector');
const NetioConnector = require('./netioConnector');
const ProjectorConnector = require('./projectorConnector');
const AnelConnector = require('./anelConnector');

const QueueManager = require('../managers/queueManager');
const UnitTimerManager = require('../managers/unitTimerManager');

class connectorCoordinator {
  constructor(io, db, config = {}) {
    this.io = io;
    this.db = db;
    this.config = config;

    // Initialize all runners
    this.connectors = {
      shell: new ShellConnector(io, db),
      netio: new NetioConnector(io, db),
      projector: new ProjectorConnector(io, db),
      anel: new AnelConnector(io, db)
    };

    // Initialize queue manager
    this.queueManager = new QueueManager(this, db, config);

    // Initialize timer manager
    this.timerManager = new UnitTimerManager(db, this.queueManager, config);

    debug('Runner Coordinator initialized with runners: %o', Object.keys(this.connectors));
    debug('Queue Manager and Timer Manager integrated and ready');
  }

  // Helper function for readable unit display
  getUnitDisplayName(unit) {
    const work = this.db.getWorkById(unit.parentId);
    const exhibition = work ? this.db.getExhibits().find(e => e.id === work.parentId) : null;

    const exhibitionName = exhibition?.name || 'Unknown Exhibition';
    const workName = work?.name || 'Unknown Work';
    const unitType = unit.unitType || 'unknown';
    const host = unit.host && unit.host !== '#nohost' ? unit.host : 'nohost';

    return `${exhibitionName} > ${workName} > ${unitType}@${host}`;
  }

  // Fast Path: Immediate execution (< 1s response requirement)
  async executeImmediate(controlData, targetState) {
    debug('🚀 IMMEDIATE execution (Fast Path): %s %s -> %s', controlData.type, controlData.id, targetState ? 'ON' : 'OFF');

    try {
      const units = this.getUnitsForControl(controlData);

      if (units.length === 0) {
        debug('No units found for immediate execution');
        return { success: true, unitsProcessed: 0 };
      }

      debug('Fast Path processing %d units', units.length);

      // Execute all units in parallel for maximum speed (bypasses queue entirely)
      const promises = units.map(unit => this.executeUnitImmediate(unit, targetState));
      const results = await Promise.all(promises);

      // Update database states for successful operations
      results.forEach(result => {
        if (result.success && result.state !== undefined) {
          this.updateUnitState(result.unit, result.state);
        }
      });

      const successCount = results.filter(r => r.success).length;
      debug('Fast Path completed: %d/%d units successful', successCount, units.length);

      return {
        success: true,
        unitsProcessed: units.length,
        successfulUnits: successCount,
        results: results,
        fastPath: true
      };

    } catch (error) {
      debug('Error in immediate execution: %s', error.message);
      throw error;
    }
  }

  // Normal Path: Queued execution with rate limiting
  async executeQueued(controlData, targetState) {
    debug('📋 QUEUED execution (Normal Path): %s %s -> %s', controlData.type, controlData.id, targetState ? 'ON' : 'OFF');

    try {
      const units = this.getUnitsForControl(controlData);

      if (units.length === 0) {
        debug('No units found for queued execution');
        return { success: true, unitsProcessed: 0 };
      }

      debug('Queuing %d units for rate-limited execution', units.length);

      // Log which units are being queued (first few for brevity)
      units.slice(0, 3).forEach(unit => {
        debug('Queuing: %s', this.getUnitDisplayName(unit));
      });
      if (units.length > 3) {
        debug('... and %d more units', units.length - 3);
      }

      // Create operations for all units
      const operations = units.map(unit => ({
        type: 'setState',
        unit: unit,
        targetState: targetState ? 1 : 0
      }));

      // Add to queue for rate-limited processing
      const queueIds = this.queueManager.addBulkOperations(operations);

      debug('Queued %d operations for rate-limited execution', operations.length);

      return {
        success: true,
        unitsProcessed: units.length,
        queueIds: queueIds,
        fastPath: false,
        message: `${units.length} operations queued for rate-limited execution`
      };

    } catch (error) {
      debug('Error in queued execution: %s', error.message);
      throw error;
    }
  }

  // Execute single unit immediately (used by fast path and queue processor)
  async executeUnitImmediate(unit, targetState) {
    try {
      const runner = this.getRunnerForUnit(unit);
      if (!runner) {
        debug('No runner found for unit type: %s', unit.unitType);
        return {
          success: false,
          unit: unit.id,
          error: 'No runner available',
          unitType: unit.unitType
        };
      }

      // Direct state change for maximum speed
      const result = await runner.setState(unit, targetState);

      // Update database on success
      if (result.success) {
        this.updateUnitState(unit.id, targetState ? 1 : 0);

        // Record activity for timer manager (resets state cooldown)
        if (this.timerManager) {
          this.timerManager.recordActivity(unit.id);
        }
      }

      return {
        success: result.success,
        unit: unit.id,
        unitType: unit.unitType,
        state: result.success ? (targetState ? 1 : 0) : unit.state,
        error: result.error,
        duration: result.duration,
        timestamp: Date.now()
      };

    } catch (error) {
      debug('Error executing unit %s immediately: %s', this.getUnitDisplayName(unit), error.message);
      return {
        success: false,
        unit: unit.id,
        error: error.message,
        unitType: unit.unitType
      };
    }
  }

  // Update unit state from runner (used by queue for getState operations)
  async updateUnitStateFromRunner(unit) {
    try {
      const runner = this.getRunnerForUnit(unit);
      if (!runner) {
        debug('No runner found for unit type: %s', unit.unitType);

        // Notify timer manager of failure
        if (this.timerManager) {
          this.timerManager.onStateCheckComplete(unit.id, false, { error: 'No runner available' });
        }

        return {
          success: false,
          error: 'No runner available',
          unitType: unit.unitType
        };
      }

      const result = await runner.getState(unit);

      if (result.success && result.state !== undefined) {
        this.updateUnitState(unit.id, result.state);
      }

      // Notify timer manager of completion (success or failure)
      if (this.timerManager) {
        this.timerManager.onStateCheckComplete(unit.id, result.success, result);
      }

      return {
        success: result.success,
        state: result.state,
        error: result.error,
        unitType: unit.unitType,
        timestamp: Date.now()
      };

    } catch (error) {
      debug('Error updating state for unit %s: %s', this.getUnitDisplayName(unit), error.message);

      // Notify timer manager of failure
      if (this.timerManager) {
        this.timerManager.onStateCheckComplete(unit.id, false, { error: error.message });
      }

      return {
        success: false,
        error: error.message,
        unitType: unit.unitType
      };
    }
  }

  // Schedule state checks for units (adds to queue)
  scheduleStateChecks(units = null) {
    if (!units) {
      units = this.db.getUnits().filter(unit => unit.automation && unit.active !== false);
    }

    debug('Scheduling state checks for %d units', units.length);

    const operations = units.map(unit => ({
      type: 'getState',
      unit: unit
    }));

    const queueIds = this.queueManager.addBulkOperations(operations);

    debug('Scheduled %d state checks (queue length now: %d)', operations.length, this.queueManager.getStats().queueLength);

    return queueIds;
  }

  // Schedule state check for single unit
  scheduleUnitStateCheck(unit) {
    const operation = {
      type: 'getState',
      unit: unit
    };

    const queueId = this.queueManager.addOperation(operation);

    debug('Scheduled state check for unit: %s', this.getUnitDisplayName(unit));

    return queueId;
  }

  // Start automatic timer-based state checks
  startAutomaticStateChecks() {
    debug('Starting automatic timer-based state checks...');
    this.timerManager.startAllTimers();
  }

  // Stop automatic state checks
  stopAutomaticStateChecks() {
    debug('Stopping automatic timer-based state checks...');
    this.timerManager.stopAllTimers();
  }

  // Handle unit lifecycle events for timer management
  onUnitAdded(unit) {
    debug('Unit added: %s', this.getUnitDisplayName(unit));
    this.timerManager.addUnitTimer(unit);
  }

  onUnitUpdated(unitId) {
    debug('Unit updated: %s', unitId);
    this.timerManager.restartUnitTimer(unitId);
  }

  onUnitDeleted(unitId) {
    debug('Unit deleted: %s', unitId);
    this.timerManager.removeUnitTimer(unitId);
  }

  // Get units for control operation
  getUnitsForControl(controlData) {
    let units = [];

    switch (controlData.type) {
      case "all":
        units = this.db.getAutomationUnits();
        break;

      case "exhibit":
        const works = this.db.getWorksByExhibit(controlData.id);
        works.forEach((work) => {
          const workUnits = this.db.getUnitsByWork(work.id).filter(u => u.automation);
          units.push(...workUnits);
        });
        break;

      case "work":
        units = this.db.getUnitsByWork(controlData.id).filter(u => u.automation);
        break;

      case "unit":
        const allUnits = this.db.getUnits();
        units = allUnits.filter(u => u.id === controlData.id);
        break;

      default:
        debug('Unknown control type: %s', controlData.type);
    }

    // Filter out inactive units
    units = units.filter(unit => unit.active !== false);

    return units;
  }

  // Get appropriate runner for unit
  getRunnerForUnit(unit) {
    const runnerMap = {
      'shell': 'shell',
      'netio': 'netio',
      'projector': 'projector',
      'anel': 'anel',
      'udp': 'netio' // UDP units use netio runner for now
    };

    const runnerKey = runnerMap[unit.unitType];
    return this.connectors[runnerKey] || null;
  }

  // Update unit state in database
  updateUnitState(unitId, newState) {
    try {
      this.db.updateUnitState(unitId, newState);
      debug('Updated unit %s state to %d', unitId, newState);
    } catch (error) {
      debug('Error updating unit %s state: %s', unitId, error.message);
    }
  }

  // Get queue statistics
  getQueueStats() {
    return this.queueManager.getStats();
  }

  // Get timer statistics  
  getTimerStats() {
    return this.timerManager.getStats();
  }

  // Get queue contents for debugging
  getQueueContents() {
    return this.queueManager.getQueueContents();
  }

  // Get all timer info for debugging
  getAllTimerInfo() {
    return this.timerManager.getAllTimerInfo();
  }

  // Update queue configuration at runtime
  updateQueueConfig(newConfig) {
    this.queueManager.updateConfig(newConfig);
  }

  // Update timer configuration at runtime
  updateTimerConfig(newConfig) {
    this.timerManager.updateConfig(newConfig);
  }

  // Clear queue (emergency use)
  clearQueue() {
    return this.queueManager.clearQueue();
  }

  // Get runner information
  getRunnerInfo() {
    const runnerInfo = {};

    Object.entries(this.connectors).forEach(([type, runner]) => {
      if (runner.getRunnerInfo) {
        runnerInfo[type] = runner.getRunnerInfo();
      }
    });

    return {
      runners: runnerInfo,
      queue: this.queueManager.getStats(),
      timers: this.timerManager.getStats(),
      coordinator: {
        totalRunners: Object.keys(this.connectors).length,
        queueEnabled: true,
        timersEnabled: true,
        fastPathEnabled: true
      }
    };
  }

  // Shutdown coordinator, queue, and timers
  shutdown() {
    debug('Runner Coordinator shutting down...');

    // Shutdown timer manager
    this.timerManager.shutdown();

    // Shutdown queue manager
    this.queueManager.shutdown();

    // Disconnect runners if they have cleanup methods
    Object.entries(this.connectors).forEach(([type, runner]) => {
      if (runner.disconnect) {
        try {
          runner.disconnect();
          debug('%s runner disconnected', type);
        } catch (error) {
          debug('Error disconnecting %s runner: %s', type, error.message);
        }
      }
    });

    debug('Runner Coordinator shutdown complete');
  }
}

module.exports = connectorCoordinator;

